package com.loja.checkout.entrega;

import com.loja.checkout.dominio.Pedido;
import java.math.BigDecimal;

/**
 * Uma opção de entrega. Para oferecer uma transportadora nova, basta criar uma
 * classe que implemente esta interface e marcá-la com {@code @Component}: ela
 * passa a ser reconhecida pelo serviço sem nenhuma outra alteração.
 */
public interface ModalidadeEntrega {

    /** Código usado pelo site, ex.: {@code EXPRESSA}. */
    String codigo();

    /** Prazo de entrega em dias. */
    int prazoDias();

    /** Frete cobrado para o pedido, arredondado em centavos. */
    BigDecimal frete(Pedido pedido);

    /** Se esta opção atende o pedido (peso, região, valor...). */
    default boolean atende(Pedido pedido) {
        return true;
    }
}
EOF
cat > entrega/EntregaBaseMaisPeso.java <<'EOF'
package com.loja.checkout.entrega;

import com.loja.checkout.dominio.Dinheiro;
import com.loja.checkout.dominio.Pedido;
import java.math.BigDecimal;

/** Base para opções que cobram um valor fixo mais um valor por kg do pedido. */
abstract class EntregaBaseMaisPeso implements ModalidadeEntrega {

    private final BigDecimal valorFixo;
    private final BigDecimal valorPorKg;

    protected EntregaBaseMaisPeso(String valorFixo, String valorPorKg) {
        this.valorFixo = new BigDecimal(valorFixo);
        this.valorPorKg = new BigDecimal(valorPorKg);
    }

    @Override
    public BigDecimal frete(Pedido pedido) {
        return Dinheiro.arredondar(valorFixo.add(valorPorKg.multiply(pedido.pesoTotalKg())));
    }
}
EOF
