public class C {
  public static void main(String[] a){
    MathContext mc = new MathContext(30);
    BigDecimal i = new BigDecimal("0.0199");
    for (String tt : new String[]{"413.80"}) {
      BigDecimal t = new BigDecimal(tt);
      for (int n=4;n<=12;n++){
        BigDecimal f = BigDecimal.ONE.add(i).pow(n, mc);
        BigDecimal d = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(f, mc));
        BigDecimal p = t.multiply(i).divide(d, mc);
        BigDecimal pr = p.setScale(2, RoundingMode.HALF_EVEN);
        System.out.println(n+"x parcela="+p.setScale(6,RoundingMode.HALF_EVEN)+" -> "+pr+" total="+pr.multiply(BigDecimal.valueOf(n))+" ajuste="+pr.multiply(BigDecimal.valueOf(n)).subtract(t));
      }
    }
    System.out.println("pix757.20="+new BigDecimal("757.20").multiply(new BigDecimal("0.05")).setScale(2,RoundingMode.HALF_EVEN));
    System.out.println("cred749.70="+new BigDecimal("749.70").multiply(new BigDecimal("0.05")).setScale(2,RoundingMode.HALF_EVEN));
    System.out.println("seg749.70="+new BigDecimal("749.70").multiply(new BigDecimal("0.01")).setScale(2,RoundingMode.HALF_EVEN));
